+ * hace que el logout de HU-11-01 RN-6 sea real y no sólo local: sin esta llamada, un token
+ * que quedara persistido por un fallo del almacén seguiría sirviendo hasta su `expiresAt`.
+ *
+ * Lanza `ApiError`/`TransportError` como cualquier otra llamada; el llamador decide qué
+ * hacer con el fallo (el cierre de sesión local se hace igual, ver `SessionProvider`).
+ */
+export async function logout(token: string, signal?: AbortSignal): Promise<void> {
+  await apiRequest<void>('/auth/logout', {
+    method: 'POST',
+    token,
+    ...(signal === undefined ? {} : { signal }),
+  });
